type RandGenerater struct {
	x int
}

func (rg *RandGenerater) Next() int {
	// 32bit乱数を生成
	return 0
}

func (rg *RandGenerater) IntN(n int) int {
	a := (rg.Next() * n) >> 32
	return a
}

func fastPow(a float64, e int) float64 {
	if e == 0 {
		return 1
	}
	k := 64 - bits.LeadingZeros(uint(e))
	ret := 1.0
	a1 := a
	for i := 0; i < k; i++ {
		if e&(1<<i) != 0 {
			ret *= a1
		}
		a1 *= a1
	}
	return ret
}

func maxInt(a int, b int) int {
	if a > b {
		return a
	}
	return b
}

func minInt(a int, b int) int {
	if a < b {
		return a
	}
	return b
}

func absInt(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

func popcount(x int) int {
	x = x - ((x >> 1) & 0x5555555555555555)

	x = (x & 0x3333333333333333) + ((x >> 2) & 0x3333333333333333)

	x = (x + (x >> 4)) & 0x0f0f0f0f0f0f0f0f
	x = x + (x >> 8)
	x = x + (x >> 16)
	x = x + (x >> 32)
	return x & 0x0000007f
}

func getScanner(file string) *bufio.Scanner {
	var scanner *bufio.Scanner
	if LOCAL_TEST {
		fp, err := os.Open(file)
		if err != nil {
			panic("Error: Can not open file ")
		}
		if !REPEAT {
			fmt.Fprintf(os.Stderr, "---CASE %s---\n", file)
		}
		scanner = bufio.NewScanner(fp)
	} else {
		scanner = bufio.NewScanner(os.Stdin)
	}
	scanner.Buffer(make([]byte, 1000000), 1000000)
	return scanner
}

func getInputs(gConst *GameConst) {
	// 例
	gConst.Scanner.Scan()
	splitedInput := strings.Split(gConst.Scanner.Text(), " ")
	N, _ := strconv.Atoi(splitedInput[0])
	M, _ := strconv.Atoi(splitedInput[1])
	V, _ := strconv.Atoi(splitedInput[2])
	gConst.PlateSize = N
	gConst.NumTakoyaki = M
	gConst.MaxVertex = V
	gConst.InitalTakoyakiPlate = NewTakoyakiPlate(gConst.PlateSize)
	for i := 0; i < N; i++ {
		gConst.Scanner.Scan()
		plateRowStr := gConst.Scanner.Text()
		for j := range plateRowStr {
			if plateRowStr[j] == '1' {
				gConst.InitalTakoyakiPlate.AddTakoyaki(i, j)
			}
		}
	}
	gConst.GoalTakoyakiPlate = NewTakoyakiPlate(gConst.PlateSize)
	for i := 0; i < N; i++ {
		gConst.Scanner.Scan()
		plateRowStr := gConst.Scanner.Text()
		for j := range plateRowStr {
			if plateRowStr[j] == '1' {
				if gConst.InitalTakoyakiPlate.ContainsTakoyaki(i, j) {
					gConst.InitialNumComplete++
				}
				gConst.GoalTakoyakiPlate.AddTakoyaki(i, j)
			}
		}
	}

	gConst.GameStatePool = sync.Pool{
		New: func() interface{} {
			s := NewGameState(gConst)
			return s
		},
	}
}

type TakoyakiPlate struct {
	Size        int // 縦横のサイズ
	NumTakoyaki int
	Field       []uint64
}

func NewTakoyakiPlate(size int) *TakoyakiPlate {
	t := TakoyakiPlate{}
	t.Size = size
	t.Field = make([]uint64, t.Size)
	return &t
}

func (plate *TakoyakiPlate) Copy() *TakoyakiPlate {
	newPlate := NewTakoyakiPlate(plate.Size)
	newPlate.Load(plate)
	return newPlate
}

func (plate *TakoyakiPlate) Load(plate2 *TakoyakiPlate) {
	plate.Size = plate2.Size
	plate.NumTakoyaki = plate2.NumTakoyaki
	for i := range plate.Field {
		plate.Field[i] = plate2.Field[i]
	}
}

func (plate *TakoyakiPlate) ContainsTakoyaki(y int, x int) bool {
	if y < 0 {
		return false
	}
	if y >= plate.Size {
		return false
	}
	if x < 0 {
		return false
	}
	return plate.Field[y]&(1<<x) != 0
}

func (plate *TakoyakiPlate) AddTakoyaki(y int, x int) {
	if plate.Field[y]&(1<<x) == 0 {
		plate.NumTakoyaki++
		plate.Field[y] |= (1 << x)
	} else {
		fmt.Fprintf(os.Stderr, "WARN: add failed. (%d, %d) already contain takoyaki.\n", x, y)
	}
}

func (plate *TakoyakiPlate) DeleteTakoyaki(y int, x int) {
	if plate.Field[y]&(1<<x) != 0 {
		plate.NumTakoyaki--
		plate.Field[y] &= ^(1 << x)
	} else {
		fmt.Fprintf(os.Stderr, "WARN: delete failed. (%d, %d) is empty.\n", x, y)
	}
}

// 現在の状態を記録するもの
type GameState struct {
	RootPos          [2]int
	JointAngles      []int          // 各関節の回転角
	HoldingTakoyaki  []bool         // 各頂点がたこ焼きを持っているか
	LastUsed         []int          // 各頂点がいつ回転を行ったか 2ターン以上前ならどの方向へも回転できる
	AllowMove        [DIRS + 1]bool // 各方向に移動可能か
	Turn             int
	NumCompleted     int
	NowTakoyakiPlate *TakoyakiPlate

	hash      uint64
	treeType  int // 使用するtree
	beamValue float64
	epsValue  float64
}

func NewGameState(gConst *GameConst) *GameState {
	g := GameState{}
	g.NumCompleted = gConst.InitialNumComplete
	g.JointAngles = make([]int, gConst.MaxVertex)
	g.HoldingTakoyaki = make([]bool, gConst.MaxVertex)
	g.LastUsed = make([]int, gConst.MaxVertex)
	for i := range g.AllowMove {
		g.AllowMove[i] = true
	}
	g.Turn = 1
	g.NowTakoyakiPlate = gConst.InitalTakoyakiPlate.Copy()
	g.epsValue = 100
	return &g
}

func (g *GameState) Copy(gConst *GameConst, tree *Tree) *GameState {
	newg := gConst.GameStatePool.Get().(*GameState)
	newg.Load(g)
	return newg
}
func (g *GameState) Load(g2 *GameState) {
	g.RootPos = g2.RootPos
	for i := range g.JointAngles {
		g.JointAngles[i] = g2.JointAngles[i]
	}
	for i := range g.HoldingTakoyaki {
		g.HoldingTakoyaki[i] = g2.HoldingTakoyaki[i]
	}
	for i := range g.LastUsed {
		g.LastUsed[i] = g2.LastUsed[i]
	}
	g.AllowMove = g2.AllowMove

	g.Turn = g2.Turn
	g.NumCompleted = g2.NumCompleted
	g.NowTakoyakiPlate.Load(g2.NowTakoyakiPlate)

	g.hash = g2.hash
	g.treeType = g2.treeType
	g.beamValue = g2.beamValue
	g.epsValue = g2.epsValue
}

func (gameState *GameState) ApplyAction(gameConst *GameConst, action *Action, tree *Tree) {
	gameConst.dataForPoss[0] = gameState.RootPos
	move := action.Move
	if move >= 0 {
		gameConst.dataForPoss[0][0] += DIRS_D[move][0]
		gameConst.dataForPoss[0][1] += DIRS_D[move][1]
		gameState.RootPos = gameConst.dataForPoss[0]
	}
	for i := 1; i < tree.NumVertex; i++ {
		parent := tree.Parent[i]
		dir := gameConst.dataForDs[parent]
		nAngle := gameState.JointAngles[i]
		rotation := action.getRotation(i)
		nAngle += ROTATIONS[rotation]
		nAngle &= 0b11
		dir += nAngle
		dir &= 0b11
		gameConst.dataForDs[i] = dir
		gameConst.dataForPoss[i][0] = gameConst.dataForPoss[parent][0] + tree.Length[i]*DIRS_D[dir][0]
		gameConst.dataForPoss[i][1] = gameConst.dataForPoss[parent][1] + tree.Length[i]*DIRS_D[dir][1]

		gameState.JointAngles[i] = nAngle
		if rotation != 0 {
			gameState.LastUsed[i] = gameState.Turn
		}
	}
	meaningful := false
	for i := 0; i < tree.NumVertex; i++ {
		if action.Pick&(1<<i) != 0 {
			if !gameState.HoldingTakoyaki[i] {
				gameState.Pick(i, gameConst.dataForPoss[i][0], gameConst.dataForPoss[i][1])
			} else {
				gameState.Release(i, gameConst.dataForPoss[i][0], gameConst.dataForPoss[i][1])
			}
			diff := absInt(gameConst.dataForPoss[i][0]-gameState.NowTakoyakiPlate.Size/2) + absInt(gameConst.dataForPoss[i][1]-gameState.NowTakoyakiPlate.Size/2)
			// gameState.epsValue += float64(diff * diff)
			gameState.epsValue += float64(diff)
			a := minInt(gameConst.dataForPoss[i][0], gameState.NowTakoyakiPlate.Size-gameConst.dataForPoss[i][0])
			b := minInt(gameConst.dataForPoss[i][1], gameState.NowTakoyakiPlate.Size-gameConst.dataForPoss[i][1])
			if a < 5 {
				gameState.epsValue += float64(5 * (5 - a))
			}
			if b < 5 {
				gameState.epsValue += float64(5 * (5 - b))
			}
			index := i
			for {
				gameState.LastUsed[index] = gameState.Turn
				if index == 0 {
					break
				}
				index = tree.Parent[index]
			}
			meaningful = true
		}
	}
	if meaningful {
		for i := range gameState.AllowMove {
			gameState.AllowMove[i] = true
		}
	} else {
		if move == -1 {
			gameState.AllowMove[4] = false
		}
		if move == 0 {
			gameState.AllowMove[4] = false
			gameState.AllowMove[2] = false
		}
		if move == 1 {
			gameState.AllowMove[4] = false
			gameState.AllowMove[3] = false
		}
		if move == 2 {
			gameState.AllowMove[4] = false
			gameState.AllowMove[0] = false
		}
		if move == 3 {
			gameState.AllowMove[4] = false
			gameState.AllowMove[1] = false
		}
	}
	gameState.Turn++

	// hash処理
	gameState.hash = 0
	gameState.hash ^= uint64(HASH_POS[gameState.RootPos[0]][gameState.RootPos[1]])
	for i := range gameState.JointAngles {
		if gameState.LastUsed[i] < gameState.Turn-1 {
			gameState.hash ^= uint64(HASH_ANGLE[i][4])
		} else {
			gameState.hash ^= uint64(HASH_ANGLE[i][gameState.JointAngles[i]])
		}
	}
	gameState.hash += uint64(gameState.beamValue * 1000000)
	gameState.hash += uint64(gameState.epsValue)
}

func (g *GameState) Pick(index int, y int, x int) {
	g.HoldingTakoyaki[index] = true
	g.NowTakoyakiPlate.DeleteTakoyaki(y, x)
}

func (g *GameState) Release(index int, y int, x int) {
	g.HoldingTakoyaki[index] = false
	g.NowTakoyakiPlate.AddTakoyaki(y, x)
	g.NumCompleted++
}

// 1ケース実行中において不変なものを保存する構造体
type GameConst struct {
	Random  *rand.Rand
	Scanner *bufio.Scanner

	GameStatePool sync.Pool

	dataForPoss [][2]int
	dataForDs   []int

	PlateSize           int
	NumTakoyaki         int
	MaxVertex           int
	InitialNumComplete  int
	InitalTakoyakiPlate *TakoyakiPlate
	GoalTakoyakiPlate   *TakoyakiPlate
}

func (g *GameConst) SetScanner(scanner *bufio.Scanner) {
	g.Scanner = scanner
}

func NewGameConst(runner *Runner) *GameConst {
	g := GameConst{}
	g.Random = rand.New(rand.NewSource(runner.randSeed))
	// g.Random = rand.New(rand.NewSource(0))

	return &g
}

func printActions(actions []*Action, gameConst *GameConst, comment bool) {
	for i := range actions {
		printAction(actions[i], gameConst, comment)
	}
}
func printAction(action *Action, gameConst *GameConst, comment bool) {
	// fmt.Println("アクションを出力")
	message := ""
	character := "."
	if action.Move == 0 {
		character = "R"
	} else if action.Move == 1 {
		character = "D"
	} else if action.Move == 2 {
		character = "L"
	} else if action.Move == 3 {
		character = "U"
	}
	message = message + character
	for i := 0; i < gameConst.MaxVertex; i++ {
		if i == 0 {
			continue
		}
		rotation := action.getRotation(i)
		character = "."
		if rotation == 1 {
			character = "R"
		} else if rotation == 2 {
			character = "L"
		}
		message = message + character
	}
	for i := 0; i < gameConst.MaxVertex; i++ {
		character = "."
		if action.Pick&(1<<i) != 0 {
			character = "P"
		}
		message = message + character
	}
	fmt.Println(message)
}

