type Solver struct {
	caseindex int
	timeLimit int // solverに与えられた時間制限 microsecond
}

func NewSolver(caseindex int, timeLimit int) *Solver {
	s := Solver{}
	s.caseindex = caseindex
	s.timeLimit = timeLimit
	return &s
}

func (s *Solver) Solve(gameConst *GameConst, trees []*Tree, start time.Time, loopIndex int, loopNum int) (*Tree, [2]int, []*Action, int) {

	maxActions := []*Action{}
	maxScore := 0.0
	_ = maxScore

	// initialPosの決定
	initialPos := [2]int{0, 0}
	initialPos[0] = gameConst.PlateSize / 2
	initialPos[1] = gameConst.PlateSize / 2
	// 行動列の決定
	gameState := NewGameState(gameConst)
	gameState.RootPos = initialPos
	bs := NewBeamSearch()
	if s.timeLimit*(1+loopIndex)/loopNum-int(time.Since(start).Microseconds()) < s.timeLimit/loopNum/2 {
		fmt.Fprintln(os.Stderr, loopIndex, loopNum, s.timeLimit*(1+loopIndex)/loopNum-int(time.Since(start).Microseconds()), s.timeLimit/loopNum/2)
	}
	bs.Init(s.caseindex, 6000, 1000, maxInt(s.timeLimit*(1+loopIndex)/loopNum-int(time.Since(start).Microseconds()), s.timeLimit/loopNum/2))
	bestTreeType := 0

	for bs.nowDepth < bs.depth {
		action, pos, treeType := bs.Run(gameState, gameConst, trees)
		if bs.nowDepth == 1 {
			initialPos = pos
			gameState.RootPos = initialPos
			bestTreeType = treeType
		}
		maxActions = append(maxActions, action)
		gameState.ApplyAction(gameConst, action, trees[bestTreeType])
		// turn backに対する修正が必要

		for i := 0; i < gameConst.MaxVertex; i++ {
			if action.getRotation(i) == 3 {
				maxActions[len(maxActions)-2].setRotation(i, 1)
				maxActions[len(maxActions)-1].setRotation(i, 1)
			}
		}
	}

	// for loop := 0; loop < 100; loop++ {
	// 	gameState := NewGameState(gameConst)
	// 	gameState.RootPos = initialPos
	// 	bs = NewBeamSearch()
	// 	bs.Init(600, 1000)
	// 	_, _ = bs.Run(gameState, gameConst, trees)
	// 	fmt.Fprintln(os.Stderr, bs.effectiveStates[50][0].beamValue, bs.effectiveStates[50][0].epsValue, bs.bestDepth)
	// }

	score := len(maxActions)

	return trees[bestTreeType], initialPos, maxActions, score
}

func (runner *Runner) doGame(file string) Result {
	result := Result{}
	scanner := getScanner(FILE + "\\" + file + ".txt")

	// 初期値設定処理

	gameConst := NewGameConst(runner)
	gameConst.SetScanner(scanner)
	// データ取得
	getInputs(gameConst)
	gameConst.dataForPoss = make([][2]int, gameConst.MaxVertex)
	gameConst.dataForDs = make([]int, gameConst.MaxVertex)

	// 検証対象外をはじく
	if gameConst.MaxVertex >= 16 {
		result.score = -1
		return result
	}

	// 初期値設定処理　ここまで
	solver := NewSolver(runner.caseIndex, int(TIME_LIMIT*19/20))
	start := time.Now()

	trees := makeTrees(gameConst)
	if SET_RANDOM_TREE {

		trees = runner.treeMaker.MakeTrees(gameConst)

		// treeMaker := TreeMaker{}
		// treeMaker.r3 = []int{0, 0, 1, 2, 3, 3, 3, 3, 3, 2}
		// treeMaker.r1 = []int{0, 4, 4, 4, 0, 0, 0, 0, 0, 4}
		// treeMaker.r2 = []int{0, -2, 1, -1, 1, 2, 3, 4, 5, -1}
		// t2 := treeMaker.MakeTrees(gameConst)
		// trees = append(trees, t2...)
	}
	loopNum := len(trees)

	// 分割数計算のための仮BeamSearch
	bs := NewBeamSearch()
	bs.Init(runner.caseIndex, 600, 1, solver.timeLimit)
	w := bs.CalcWidth(0, trees[0].NumBase, gameConst)

	loopNum = minInt(loopNum, maxInt(w/1500, 1))
	// fmt.Fprintln(os.Stderr, runner.caseIndex, w)

	var minTree *Tree
	minScore := INF
	var minActions []*Action
	minInitialPos := [2]int{}

	for loop := 0; loop < loopNum; loop++ {
		var t []*Tree
		if loop < loopNum-1 {
			t = trees[loop : loop+1]
		} else {
			t = trees[loop:]
		}
		tree, initialPos, actions, score := solver.Solve(gameConst, t, start, loop, loopNum)
		if score < minScore {
			minScore = score
			minTree = tree
			minInitialPos = initialPos
			minActions = actions
		}
	}
	fmt.Fprintln(os.Stderr, "miss:", missCount)
	duration := time.Since(start).Microseconds()
	// アクションを出力
	if !LOCAL_TEST || (!SUCCESSIVE && PRINT_ACTION) {
		printTree(minTree, gameConst, false)
		fmt.Println(minInitialPos[0], minInitialPos[1])
		printActions(minActions, gameConst, false)
	}

	if LOCAL_TEST {
		gameState := NewGameState(gameConst)
		gameState.RootPos = minInitialPos
		minScore = calcScore(gameState, minTree, minActions, gameConst)
	}

	result.score = minScore
	// result.score = int(duration)
	result.loopNum = int(duration)

	if duration >= TIME_LIMIT_STRICT {
		result.score = -1
	}

	return result
}

