func calcScore(gameState *GameState, tree *Tree, actions []*Action, gameConst *GameConst) int {
	// 正当性チェック
	for i := range actions {
		gameState.ApplyAction(gameConst, actions[i], tree)
	}
	score := len(actions)
	return score
}

